"""Generate scoped CloudFormation plans; this script creates no resources."""
import json
from pathlib import Path
base=Path(__file__).parent
ref=lambda x:{'Ref':x}
sub=lambda x:{'Fn::Sub':x}
get=lambda x,y:{'Fn::GetAtt':[x,y]}
trust=lambda service:{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':service},'Action':'sts:AssumeRole'}]}
stmt=lambda actions,resource:{'Effect':'Allow','Action':actions,'Resource':resource}
def role(service,statements):return {'Type':'AWS::IAM::Role','Properties':{'AssumeRolePolicyDocument':trust(service),'Policies':[{'PolicyName':'AstraScopedResources','PolicyDocument':{'Version':'2012-10-17','Statement':statements}}]}}
logarn=sub('arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/*/informatics-astra-*:*')
secret={'Type':'AWS::SecretsManager::Secret','Properties':{'Name':'informatics-astra-staging/runtime','Description':'Existing worker and OpenAI credentials; populate after infrastructure creation.'}}
bucket={'Type':'AWS::S3::Bucket','DeletionPolicy':'Retain','UpdateReplacePolicy':'Retain','Properties':{'BucketName':sub('informatics-astra-staging-${AWS::AccountId}-${AWS::Region}'),'PublicAccessBlockConfiguration':{'BlockPublicAcls':True,'BlockPublicPolicy':True,'IgnorePublicAcls':True,'RestrictPublicBuckets':True},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]},'OwnershipControls':{'Rules':[{'ObjectOwnership':'BucketOwnerEnforced'}]}}}
repo={'Type':'AWS::ECR::Repository','Properties':{'RepositoryName':'informatics-astra-staging','ImageTagMutability':'IMMUTABLE','ImageScanningConfiguration':{'ScanOnPush':False},'LifecyclePolicy':{'LifecyclePolicyText':json.dumps({'rules':[{'rulePriority':1,'selection':{'tagStatus':'any','countType':'imageCountMoreThan','countNumber':2},'action':{'type':'expire'}}]})}}}
buildspec={'version':0.2,'phases':{'pre_build':{'commands':['aws ecr get-login-password --region "$AWS_DEFAULT_REGION" | docker login --username AWS --password-stdin "$REGISTRY"']},'build':{'commands':['docker build --platform linux/amd64 -t "$REGISTRY/informatics-astra-staging:$IMAGE_TAG" .']},'post_build':{'commands':['docker push "$REGISTRY/informatics-astra-staging:$IMAGE_TAG"']}}}
bootstrap={'AWSTemplateFormatVersion':'2010-09-09','Description':'Astra staging build and encrypted state; no quantum permissions.','Resources':{'State':bucket,'Repository':repo,'RuntimeSecret':secret,
'BuildRole':role('codebuild.amazonaws.com',[stmt(['ecr:GetAuthorizationToken'],'*'),stmt(['ecr:BatchCheckLayerAvailability','ecr:CompleteLayerUpload','ecr:InitiateLayerUpload','ecr:PutImage','ecr:UploadLayerPart','ecr:BatchGetImage','ecr:GetDownloadUrlForLayer'],get('Repository','Arn')),stmt(['s3:GetObject'],sub('${State.Arn}/build/*')),stmt(['logs:CreateLogStream','logs:PutLogEvents'],logarn)]),
'BuildLogs':{'Type':'AWS::Logs::LogGroup','Properties':{'LogGroupName':'/aws/codebuild/informatics-astra-staging','RetentionInDays':7}},
'Build':{'Type':'AWS::CodeBuild::Project','Properties':{'Name':'informatics-astra-staging','ServiceRole':get('BuildRole','Arn'),'TimeoutInMinutes':20,'QueuedTimeoutInMinutes':5,'ConcurrentBuildLimit':1,'Artifacts':{'Type':'NO_ARTIFACTS'},'Source':{'Type':'S3','Location':sub('${State}/build/source.zip'),'BuildSpec':json.dumps(buildspec)},'Environment':{'Type':'LINUX_CONTAINER','ComputeType':'BUILD_GENERAL1_SMALL','Image':'aws/codebuild/standard:7.0','PrivilegedMode':True,'EnvironmentVariables':[{'Name':'REGISTRY','Value':sub('${AWS::AccountId}.dkr.ecr.${AWS::Region}.amazonaws.com')},{'Name':'IMAGE_TAG','Value':'candidate-1'}]},'LogsConfig':{'CloudWatchLogs':{'Status':'ENABLED','GroupName':ref('BuildLogs')}}}}},'Outputs':{'Bucket':{'Value':ref('State')},'SecretArn':{'Value':ref('RuntimeSecret')},'RepositoryUri':{'Value':get('Repository','RepositoryUri')}}}
params={'StateBucket':{'Type':'String'},'SecretArn':{'Type':'String'},'ImageUri':{'Type':'String'},'DispatcherKey':{'Type':'String','Default':'build/dispatcher.zip'},'ScheduleState':{'Type':'String','Default':'DISABLED','AllowedValues':['DISABLED','ENABLED']}}
statearn=sub('arn:${AWS::Partition}:s3:::${StateBucket}')
list_prefix=lambda prefix:{**stmt(['s3:ListBucket'],statearn),'Condition':{'StringLike':{'s3:prefix':[prefix]}}}
workerrole=role('lambda.amazonaws.com',[stmt(['secretsmanager:GetSecretValue'],ref('SecretArn')),list_prefix('state/*'),stmt(['s3:GetObject','s3:PutObject'],[sub('arn:${AWS::Partition}:s3:::${StateBucket}/state/*'),sub('arn:${AWS::Partition}:s3:::${StateBucket}/results/*')]),stmt(['logs:CreateLogStream','logs:PutLogEvents'],logarn)])
dispatchrole=role('lambda.amazonaws.com',[stmt(['secretsmanager:GetSecretValue'],ref('SecretArn')),list_prefix('allowance/*'),stmt(['s3:GetObject','s3:PutObject'],sub('arn:${AWS::Partition}:s3:::${StateBucket}/allowance/*')),stmt(['lambda:InvokeFunction'],get('Worker','Arn')),stmt(['logs:CreateLogStream','logs:PutLogEvents'],logarn)])
worker={'Type':'AWS::Lambda::Function','Properties':{'FunctionName':'informatics-astra-staging-worker','Role':get('WorkerRole','Arn'),'PackageType':'Image','Code':{'ImageUri':ref('ImageUri')},'MemorySize':4096,'Timeout':900,'EphemeralStorage':{'Size':4096},'ReservedConcurrentExecutions':1,'Environment':{'Variables':{'ASTRA_SECRET_ARN':ref('SecretArn'),'ASTRA_STATE_BUCKET':ref('StateBucket')}}}}
dispatch={'Type':'AWS::Lambda::Function','Properties':{'FunctionName':'informatics-astra-staging-dispatch','Role':get('DispatcherRole','Arn'),'Runtime':'python3.12','Handler':'dispatch.handler','Code':{'S3Bucket':ref('StateBucket'),'S3Key':ref('DispatcherKey')},'MemorySize':128,'Timeout':15,'ReservedConcurrentExecutions':1,'Environment':{'Variables':{'ASTRA_SECRET_ARN':ref('SecretArn'),'ASTRA_STATE_BUCKET':ref('StateBucket'),'ASTRA_WORKER_NAME':ref('Worker')}}}}
resources={'WorkerRole':workerrole,'DispatcherRole':dispatchrole,'Worker':worker,'Dispatcher':dispatch,
'WorkerLogs':{'Type':'AWS::Logs::LogGroup','Properties':{'LogGroupName':'/aws/lambda/informatics-astra-staging-worker','RetentionInDays':7}},'DispatcherLogs':{'Type':'AWS::Logs::LogGroup','Properties':{'LogGroupName':'/aws/lambda/informatics-astra-staging-dispatch','RetentionInDays':7}},
'InvokeConfig':{'Type':'AWS::Lambda::EventInvokeConfig','Properties':{'FunctionName':ref('Worker'),'Qualifier':'$LATEST','MaximumRetryAttempts':0,'MaximumEventAgeInSeconds':60}},
'Tick':{'Type':'AWS::Events::Rule','Properties':{'Name':'informatics-astra-staging-dispatch','ScheduleExpression':'rate(1 minute)','State':ref('ScheduleState'),'Targets':[{'Arn':get('Dispatcher','Arn'),'Id':'dispatcher','RetryPolicy':{'MaximumRetryAttempts':0}}]}},
'TickPermission':{'Type':'AWS::Lambda::Permission','Properties':{'FunctionName':ref('Dispatcher'),'Action':'lambda:InvokeFunction','Principal':'events.amazonaws.com','SourceArn':get('Tick','Arn')}}}
runtime={'AWSTemplateFormatVersion':'2010-09-09','Description':'On-demand Astra staging CPU worker. No function URL, GPU or Braket permission.','Parameters':params,'Resources':resources}
bootstrap['Resources']['StateTLS']={'Type':'AWS::S3::BucketPolicy','Properties':{'Bucket':ref('State'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Deny','Principal':'*','Action':'s3:*','Resource':[get('State','Arn'),sub('${State.Arn}/*')],'Condition':{'Bool':{'aws:SecureTransport':'false'}}}]}}}
for name,value in [('bootstrap.template.json',bootstrap),('runtime.template.json',runtime)]: (base/name).write_text(json.dumps(value,indent=2)+'\n')
print('Wrote bootstrap and runtime plans; scheduler defaults to disabled.')
